    // <=> C - B <= k*D <= C - A
    // <=> k >= ceil((C-B)/D)  e  k <= floor((C-A)/D)

    long long lo = (C - B + D - 1) / D; // menor k com k*D >= C - B
    if (lo < 1) lo = 1;                 // pelo menos 1 dose
    long long hi = (C - A) / D;         // maior k com k*D <= C - A

    cout << (lo <= hi ? 'S' : 'N') << '\n';
    return 0;
